	return scanEntitlement(q.QueryRow(ctx,
		`SELECT `+entitlementColumns+`
		 FROM entitlements
		 WHERE team_id = $1 AND type = $2 AND expires_at = $3`,
		teamID, typ, expiresAt.UTC()))
}

